cat > about.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>About</title>
<!-- Relative, not root-absolute: the site is served from /test-project/ on
     project Pages, so "/favicon.ico" would resolve to the user-site root. -->
<link rel="icon" href="favicon.ico" sizes="32x32">
<link rel="icon" href="favicon.svg" type="image/svg+xml">
<style>
  html, body {
    height: 100%;
    margin: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #0f172a;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  }
  h1 {
    color: #f8fafc;
    font-size: 3rem;
    font-weight: 600;
  }
  p, li {
    color: #cbd5e1;
    font-size: 1.125rem;
    line-height: 1.6;
    max-width: 40rem;
    padding: 0 1.5rem;
  }
  a {
    color: #f8fafc;
    text-decoration: underline;
  }
</style>
</head>
<body>
<h1>About</h1>
<p>This is a single static page. No build step, no dependencies. It shows one centered greeting, "Hello, and welcome.", on a dark background, and it is deployed with GitHub Pages.</p>
<p><a href="index.html">Back to home</a></p>
</body>
</html>
EOF
grep -q '<title>About</title>' about.html && grep -q '<h1>About</h1>' about.html && grep -q 'No build step, no dependencies.' about.html && grep -q 'href="favicon.svg"' about.html && grep -q 'href="index.html"' about.html && echo ok
git add about.html && git commit -q -m "Add about page

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>" && git log --oneline -1
